/**
 * Lightweight self-contained ISO/IEC 18004 QR Code SVG Generator (Versions 1-10, EC Level M, Byte Mode)
 * Zero external network dependencies — safe for live events & offline demos.
 */
(function (global) {
  'use strict';

  var GF_EXP = new Uint8Array(512);
  var GF_LOG = new Uint8Array(256);
  (function initGF() {
    var x = 1;
    for (var i = 0; i < 255; i++) {
      GF_EXP[i] = x;
      GF_LOG[x] = i;
      x <<= 1;
      if (x & 0x100) x ^= 0x11d;
    }
    for (var j = 255; j < 512; j++) {
      GF_EXP[j] = GF_EXP[j - 255];
    }
  })();

  function gfMul(a, b) {
    if (a === 0 || b === 0) return 0;
    return GF_EXP[GF_LOG[a] + GF_LOG[b]];
  }

  function rsGeneratorPoly(ecLen) {
    var poly = [1];
    for (var i = 0; i < ecLen; i++) {
      var next = new Array(poly.length + 1).fill(0);
      var factor = GF_EXP[i];
      for (var j = 0; j < poly.length; j++) {
        next[j] ^= poly[j];
        next[j + 1] ^= gfMul(poly[j], factor);
      }
      poly = next;
    }
    return poly;
  }

  function rsComputeEC(data, ecLen) {
    var gen = rsGeneratorPoly(ecLen);
    var res = new Array(ecLen).fill(0);
    for (var i = 0; i < data.length; i++) {
      var factor = data[i] ^ res[0];
      res.shift();
      res.push(0);
      if (factor !== 0) {
        for (var j = 0; j < ecLen; j++) {
          res[j] ^= gfMul(gen[j + 1], factor);
        }
      }
    }
    return res;
  }

  // Level M specs (Versions 1..10): [version, ecPerBlock, [[count, dataLen], ...], alignPositions, remainderBits]
  var SPECS_M = [
    null,
    [1,  10, [[1, 16]],            [],            0],
    [2,  16, [[1, 28]],            [6, 18],       7],
    [3,  26, [[1, 44]],            [6, 22],       7],
    [4,  18, [[2, 32]],            [6, 26],       7],
    [5,  24, [[2, 43]],            [6, 30],       7],
    [6,  16, [[4, 27]],            [6, 34],       7],
    [7,  18, [[4, 31]],            [6, 22, 38],   0],
    [8,  22, [[2, 38], [2, 39]],   [6, 24, 42],   0],
    [9,  22, [[3, 36], [2, 37]],   [6, 26, 46],   0],
    [10, 26, [[4, 43], [1, 44]],   [6, 28, 50],   0]
  ];

  function utf8Bytes(str) {
    if (typeof TextEncoder !== 'undefined') {
      return Array.from(new TextEncoder().encode(str));
    }
    var out = [];
    for (var i = 0; i < str.length; i++) {
      var c = str.charCodeAt(i);
      if (c < 0x80) out.push(c);
      else if (c < 0x800) {
        out.push(0xc0 | (c >> 6), 0x80 | (c & 0x3f));
      } else {
        out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 0x3f), 0x80 | (c & 0x3f));
      }
    }
    return out;
  }

  function totalDataBytes(spec) {
    var sum = 0;
    for (var i = 0; i < spec[2].length; i++) {
      sum += spec[2][i][0] * spec[2][i][1];
    }
    return sum;
  }

  function chooseVersion(byteLen) {
    for (var v = 1; v <= 10; v++) {
      var cap = totalDataBytes(SPECS_M[v]);
      var countBits = v <= 9 ? 8 : 16;
      var maxPayload = Math.floor((cap * 8 - 4 - countBits) / 8);
      if (byteLen <= maxPayload) return v;
    }
    throw new Error('QR payload exceeds version 10 capacity (' + byteLen + ' bytes)');
  }

  function encodeData(bytes, version) {
    var spec = SPECS_M[version];
    var capBytes = totalDataBytes(spec);
    var bits = [];
    function pushBits(val, len) {
      for (var i = len - 1; i >= 0; i--) {
        bits.push((val >> i) & 1);
      }
    }

    pushBits(4, 4); // Byte mode indicator
    pushBits(bytes.length, version <= 9 ? 8 : 16);
    for (var i = 0; i < bytes.length; i++) {
      pushBits(bytes[i], 8);
    }

    var capBits = capBytes * 8;
    var term = Math.min(4, capBits - bits.length);
    pushBits(0, term);
    while (bits.length % 8 !== 0) bits.push(0);

    var codewords = [];
    for (var j = 0; j < bits.length; j += 8) {
      var b = 0;
      for (var k = 0; k < 8; k++) b = (b << 1) | bits[j + k];
      codewords.push(b);
    }

    var pad = [0xec, 0x11];
    var pIdx = 0;
    while (codewords.length < capBytes) {
      codewords.push(pad[pIdx % 2]);
      pIdx++;
    }

    // Split into blocks, compute EC, interleave
    var ecLen = spec[1];
    var dataBlocks = [];
    var ecBlocks = [];
    var offset = 0;
    for (var g = 0; g < spec[2].length; g++) {
      var count = spec[2][g][0];
      var dLen = spec[2][g][1];
      for (var c = 0; c < count; c++) {
        var blk = codewords.slice(offset, offset + dLen);
        offset += dLen;
        dataBlocks.push(blk);
        ecBlocks.push(rsComputeEC(blk, ecLen));
      }
    }

    var maxDataLen = 0;
    for (var d = 0; d < dataBlocks.length; d++) {
      if (dataBlocks[d].length > maxDataLen) maxDataLen = dataBlocks[d].length;
    }

    var interleaved = [];
    for (var col = 0; col < maxDataLen; col++) {
      for (var r = 0; r < dataBlocks.length; r++) {
        if (col < dataBlocks[r].length) interleaved.push(dataBlocks[r][col]);
      }
    }
    for (var ecol = 0; ecol < ecLen; ecol++) {
      for (var er = 0; er < ecBlocks.length; er++) {
        interleaved.push(ecBlocks[er][ecol]);
      }
    }

    var outBits = [];
    for (var m = 0; m < interleaved.length; m++) {
      for (var s = 7; s >= 0; s--) outBits.push((interleaved[m] >> s) & 1);
    }
    for (var rb = 0; rb < spec[4]; rb++) outBits.push(0);
    return outBits;
  }

  function bchFormatInfo(mask) {
    // EC Level M = 00 -> 5-bit value = (0 << 3) | mask = mask
    var data = mask << 10;
    var poly = 0x537;
    var rem = data;
    for (var i = 14; i >= 10; i--) {
      if ((rem >> i) & 1) rem ^= (poly << (i - 10));
    }
    return ((mask << 10) | rem) ^ 0x5412;
  }

  function bchVersionInfo(version) {
    var data = version << 12;
    var poly = 0x1f25;
    var rem = data;
    for (var i = 17; i >= 12; i--) {
      if ((rem >> i) & 1) rem ^= (poly << (i - 12));
    }
    return (version << 12) | rem;
  }

  function buildMatrix(version, bitStream) {
    var size = version * 4 + 17;
    var modules = [];
    var isFunc = [];
    for (var r = 0; r < size; r++) {
      modules.push(new Int8Array(size));
      isFunc.push(new Uint8Array(size));
    }

    function setFunc(row, col, dark) {
      if (row < 0 || row >= size || col < 0 || col >= size) return;
      modules[row][col] = dark ? 1 : 0;
      isFunc[row][col] = 1;
    }

    function drawFinder(top, left) {
      for (var dy = -1; dy <= 7; dy++) {
        for (var dx = -1; dx <= 7; dx++) {
          var r = top + dy;
          var c = left + dx;
          if (r < 0 || r >= size || c < 0 || c >= size) continue;
          var dist = Math.max(Math.abs(dx - 3), Math.abs(dy - 3));
          var dark = dist !== 2 && dist !== 4;
          setFunc(r, c, dark);
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, size - 7);
    drawFinder(size - 7, 0);

    // Timing patterns
    for (var i = 8; i < size - 8; i++) {
      setFunc(6, i, i % 2 === 0);
      setFunc(i, 6, i % 2 === 0);
    }

    // Alignment patterns
    var pos = SPECS_M[version][3];
    for (var ai = 0; ai < pos.length; ai++) {
      for (var aj = 0; aj < pos.length; aj++) {
        if ((ai === 0 && aj === 0) ||
            (ai === 0 && aj === pos.length - 1) ||
            (ai === pos.length - 1 && aj === 0)) {
          continue;
        }
        var cr = pos[ai];
        var cc = pos[aj];
        for (var dy = -2; dy <= 2; dy++) {
          for (var dx = -2; dx <= 2; dx++) {
            var d = Math.max(Math.abs(dx), Math.abs(dy));
            setFunc(cr + dy, cc + dx, d === 0 || d === 2);
          }
        }
      }
    }

    // Dark module + reserve format info
    setFunc(size - 8, 8, true);
    for (var f = 0; f <= 8; f++) {
      if (f !== 6) {
        setFunc(8, f, false);
        setFunc(f, 8, false);
      }
    }
    for (var f2 = 0; f2 < 8; f2++) {
      setFunc(8, size - 1 - f2, false);
      if (f2 < 7) setFunc(size - 1 - f2, 8, false);
    }

    // Reserve version info for v >= 7
    if (version >= 7) {
      var vInfo = bchVersionInfo(version);
      for (var vi = 0; vi < 18; vi++) {
        var dark = ((vInfo >> vi) & 1) === 1;
        var vr = Math.floor(vi / 3);
        var vc = size - 11 + (vi % 3);
        setFunc(vr, vc, dark);
        setFunc(vc, vr, dark);
      }
    }

    // Place data bits in zigzag
    var bitIdx = 0;
    for (var right = size - 1; right >= 1; right -= 2) {
      if (right === 6) right = 5;
      for (var vert = 0; vert < size; vert++) {
        for (var j = 0; j < 2; j++) {
          var x = right - j;
          var upward = ((right + 1) & 2) === 0;
          var y = upward ? size - 1 - vert : vert;
          if (!isFunc[y][x] && bitIdx < bitStream.length) {
            modules[y][x] = bitStream[bitIdx];
            bitIdx++;
          }
        }
      }
    }

    function applyMask(maskId) {
      var grid = modules.map(function (row) { return Int8Array.from(row); });
      for (var r = 0; r < size; r++) {
        for (var c = 0; c < size; c++) {
          if (isFunc[r][c]) continue;
          var invert = false;
          switch (maskId) {
            case 0: invert = (r + c) % 2 === 0; break;
            case 1: invert = r % 2 === 0; break;
            case 2: invert = c % 3 === 0; break;
            case 3: invert = (r + c) % 3 === 0; break;
            case 4: invert = (Math.floor(r / 2) + Math.floor(c / 3)) % 2 === 0; break;
            case 5: invert = ((r * c) % 2 + (r * c) % 3) === 0; break;
            case 6: invert = (((r * c) % 2 + (r * c) % 3) % 2) === 0; break;
            case 7: invert = (((r + c) % 2 + (r * c) % 3) % 2) === 0; break;
          }
          if (invert) grid[r][c] ^= 1;
        }
      }

      // Draw format info (ISO/IEC 18004 Figure 25: bit 14 MSB -> bit 0 LSB)
      var fmt = bchFormatInfo(maskId);
      for (var k = 0; k < 15; k++) {
        var bit = (fmt >> k) & 1;
        if (k < 6) grid[k][8] = bit;
        else if (k === 6) grid[7][8] = bit;
        else if (k === 7) grid[8][8] = bit;
        else grid[size - 15 + k][8] = bit;

        if (k < 8) grid[8][size - 1 - k] = bit;
        else if (k === 8) grid[8][7] = bit;
        else grid[8][14 - k] = bit;
      }
      grid[size - 8][8] = 1;
      return grid;
    }

    function penalty(grid) {
      var score = 0;
      for (var r = 0; r < size; r++) {
        var runColor = -1, runLen = 0;
        for (var c = 0; c < size; c++) {
          if (grid[r][c] === runColor) {
            runLen++;
            if (runLen === 5) score += 3;
            else if (runLen > 5) score += 1;
          } else {
            runColor = grid[r][c];
            runLen = 1;
          }
        }
      }
      for (var c2 = 0; c2 < size; c2++) {
        var runColor2 = -1, runLen2 = 0;
        for (var r2 = 0; r2 < size; r2++) {
          if (grid[r2][c2] === runColor2) {
            runLen2++;
            if (runLen2 === 5) score += 3;
            else if (runLen2 > 5) score += 1;
          } else {
            runColor2 = grid[r2][c2];
            runLen2 = 1;
          }
        }
      }
      for (var r3 = 0; r3 < size - 1; r3++) {
        for (var c3 = 0; c3 < size - 1; c3++) {
          var v = grid[r3][c3];
          if (v === grid[r3][c3 + 1] && v === grid[r3 + 1][c3] && v === grid[r3 + 1][c3 + 1]) {
            score += 3;
          }
        }
      }
      var darkCount = 0;
      for (var r4 = 0; r4 < size; r4++) {
        for (var c4 = 0; c4 < size; c4++) {
          if (grid[r4][c4]) darkCount++;
        }
      }
      var pct = Math.abs((darkCount * 100) / (size * size) - 50);
      score += Math.floor(pct / 5) * 10;
      return score;
    }

    var bestGrid = null;
    var bestScore = Infinity;
    for (var m = 0; m < 8; m++) {
      var g = applyMask(m);
      var s = penalty(g);
      if (s < bestScore) {
        bestScore = s;
        bestGrid = g;
      }
    }
    return bestGrid;
  }

  function toSvgString(text, opts) {
    opts = opts || {};
    var margin = typeof opts.margin === 'number' ? opts.margin : 2;
    var darkColor = opts.darkColor || '#0F1019';
    var lightColor = opts.lightColor || '#FFFFFF';
    var bytes = utf8Bytes(String(text || ''));
    var version = chooseVersion(bytes.length);
    var bitStream = encodeData(bytes, version);
    var grid = buildMatrix(version, bitStream);
    var size = grid.length;
    var total = size + margin * 2;

    var paths = [];
    for (var r = 0; r < size; r++) {
      for (var c = 0; c < size; c++) {
        if (grid[r][c] === 1) {
          paths.push('M' + (c + margin) + ',' + (r + margin) + 'h1v1h-1z');
        }
      }
    }

    return (
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + total + ' ' + total +
      '" shape-rendering="crispEdges" role="img" aria-label="QR Code">' +
      '<rect width="100%" height="100%" fill="' + lightColor + '"/>' +
      '<path d="' + paths.join('') + '" fill="' + darkColor + '"/>' +
      '</svg>'
    );
  }

  function render(el, text, opts) {
    if (!el) return;
    el.innerHTML = toSvgString(text, opts);
  }

  global.TepaQRCode = {
    toSvgString: toSvgString,
    render: render
  };
})(typeof window !== 'undefined' ? window : globalThis);
